• try: Declares a guarded region. Any exception thrown within this block terminates try execution and jumps to the matching catch.
• catch: Matches the thrown exception type. Java supports multi-catch blocks: catch(IOException | SQLException e).
• finally: Guarantees resource deallocation (closing file handles, database connections, socket streams).
• throw: Programmatically triggers an exception: if (age < 18) throw new InvalidAgeException('Not eligible');
• throws: Listed in method signatures: public void readFile() throws IOException, SQLException { ... }

class InvalidBalanceException extends Exception {
    public InvalidBalanceException(String msg) { super(msg); }
}
public class BankAccount {
    private double balance = 1000;
    public void withdraw(double amount) throws InvalidBalanceException {
        if (amount > balance) throw new InvalidBalanceException('Insufficient funds');
        balance -= amount;
    }
    public static void main(String[] args) {
        BankAccount acc = new BankAccount();
        try {
            acc.withdraw(1500);
        } catch (InvalidBalanceException e) {
            System.err.println('Caught Exception: ' + e.getMessage());
        } finally {
            System.out.println('Audit log updated; connection closed.');
        }
    }
}
